syntax:
void* ptr = malloc(size_t size); // Allocate memory block of specified size
// Check for success: if (ptr == NULL) handle error
// Use the allocated memory
// Free memory when done: free(ptr);

code_example:
#include <stdio.h>
#include <stdlib.h>
int main() {
    size_t size = 1024 * 1024 * 1024; // 1 GB
    void *block = malloc(size);
    if (block == NULL) {
        printf("Memory allocation failed at 1 GB\n");
    } else {
        printf("Successfully allocated 1 GB of memory\n");
        free(block);
    }
    // Attempt to allocate increasingly larger blocks to find system limits
    size_t test_size = size;
    while ((block = malloc(test_size)) != NULL) {
        printf("Allocated %zu bytes\n", test_size);
        free(block);
        test_size *= 2; // Double the size each iteration
    }
    printf("Failed to allocate %zu bytes, system limit reached or fragmentation issue\n", test_size);
    return 0;
}
